library(ggplot2);library(patchwork)
out<-'E:/cohort_rds_stage_20260925/life_course_v3_20260928';old<-'E:/cohort_rds_stage_20260925/life_course_v2_20260928';dir.create(file.path(out,'figures'),showWarnings=FALSE)
theme_set(theme_classic(base_size=10,base_family='Arial')+theme(strip.background=element_blank(),strip.text=element_text(face='bold'),legend.position='bottom',plot.title=element_text(face='bold',size=12)))
savep<-function(p,n,w=10,h=5){for(ext in c('png','pdf','svg')){args<-list(filename=file.path(out,'figures',paste0(n,'.',ext)),plot=p,width=w,height=h,bg='white');if(ext=='png')args$dpi<-320;if(ext=='pdf')args$device<-cairo_pdf;if(ext=='svg')args$device<-svglite::svglite;do.call(ggsave,args)}}
labs<-c(male='Male vs female',low_birthweight='Low birthweight',ses='Early socioeconomic disadvantage',pregnancy_continued_smoke='Prenatal smoking proxy',respondent_asthma='Parent asthma',atopy3='Atopy at age 3',bmi3_z='BMI at age 3 (per SD)',ever_asthma3='Ever-asthma report by age 3',childhood_symptom='Childhood respiratory symptoms')
eq<-read.csv(file.path(out,'cohort_equivalence_pairwise.csv'));z<-eq[eq$bound=='primary',];z$factor<-factor(labs[z$term],levels=labs[c('male','low_birthweight','ses','pregnancy_continued_smoke')]);z$comparison<-factor(z$comparison,levels=rev(c('MCS/NCDS','MCS/BCS70','NCDS/BCS70')))
p<-ggplot(z,aes(ROR,comparison,color=equivalent))+annotate('rect',xmin=.8,xmax=1.25,ymin=-Inf,ymax=Inf,fill='#E7EDF1',alpha=.8)+geom_vline(xintercept=c(.8,1.25),color='#7B8A93')+geom_vline(xintercept=c(.85,1.18),lty=3,color='#9F7564')+geom_vline(xintercept=1,lty=2,color='grey60')+geom_errorbar(aes(xmin=lower90,xmax=upper90),width=.15,orientation='y')+geom_point(size=2)+facet_wrap(~factor,ncol=2)+scale_x_log10()+scale_color_manual(values=c('TRUE'='#557D9E','FALSE'='#B2816B'),labels=c('Equivalence not established','Within primary equivalence bounds'))+labs(x='Ratio of RRs (90% CI)',y=NULL,color=NULL,title='Practical equivalence depends on the factor and the chosen margin')
savep(p,'01_cohort_equivalence',11,6)
st<-read.csv(file.path(out,'stage_interactions.csv'));z<-st[st$method=='stage_specific_wave',];z$factor<-factor(labs[z$term],levels=rev(labs[z$term]));z$evidence<-z$q_BH<.05
p<-ggplot(z,aes(stage_ROR,factor,color=evidence))+geom_vline(xintercept=1,lty=2,color='grey60')+geom_errorbar(aes(xmin=lower,xmax=upper),width=.15,orientation='y')+geom_point(size=2)+scale_x_log10()+scale_color_manual(values=c('TRUE'='#557D9E','FALSE'='#B2816B'),labels=c('BH q >= 0.05','BH q < 0.05'))+labs(x='RR(symptom emergence) / RR(persistence), 95% CI',y=NULL,color=NULL,title='Susceptibility associations differ between transition stages')
savep(p,'02_transition_stage_interactions',9,5)
b<-read.csv(file.path(out,'child_to_adult_burden_table.csv'));z<-b[b$definition=='two_recent_windows',];z$cohort<-factor(z$cohort,levels=c('NCDS','BCS70'));z$phenotype<-factor(z$phenotype,levels=c('never','isolated','repeated'));z$adult_category<-factor(z$adult_category,levels=c('repeated','isolated','none'));z$xlab<-paste0(z$phenotype,'\n(n = ',z$total,')');z$xlab<-factor(z$xlab,levels=unique(z$xlab));z$percent<-sprintf('%.1f%%',100*z$weighted_probability)
p<-ggplot(z,aes(xlab,weighted_probability,fill=adult_category))+geom_col(width=.72)+geom_text(aes(label=percent),position=position_stack(vjust=.5),size=3.3)+facet_wrap(~cohort,scales='free_x')+scale_y_continuous(labels=scales::label_percent())+coord_cartesian(ylim=c(0,1))+scale_fill_manual(values=c(repeated='#7897AF',isolated='#B7CBD7',none='#E4EBEF'),breaks=c('none','isolated','repeated'),labels=c('0 positive adult waves','1 positive adult wave','>=2 positive adult waves'))+labs(x='Childhood recent-symptom phenotype',y='Adult burden category (weighted %)',fill=NULL,title='Repeated childhood symptoms identify greater adult reporting burden')
savep(p,'03_child_to_adult_burden',11,5)
r<-read.csv(file.path(out,'new_model_results.csv'));z<-r[r$method=='IPCW'&r$term%in%c('phenotypeisolated','phenotyperepeated')&r$endpoint%in%c('child_phenotype_adult_two_recent_windows','adult_repeated_six_two_recent_windows'),];z$phenotype<-factor(z$term,levels=c('phenotyperepeated','phenotypeisolated'),labels=c('Repeated vs never','Isolated vs never'));z$endpoint<-factor(z$endpoint,levels=c('child_phenotype_adult_two_recent_windows','adult_repeated_six_two_recent_windows'),labels=c('Average adult reporting','>=2 positive waves out of 6'));pd<-position_dodge(width=.5)
p<-ggplot(z,aes(RR,phenotype,color=endpoint))+geom_vline(xintercept=1,lty=2,color='grey60')+geom_errorbar(aes(xmin=lower,xmax=upper),orientation='y',width=.15,position=pd)+geom_point(size=2,position=pd)+facet_wrap(~cohort)+scale_x_log10()+scale_color_manual(values=c('#557D9E','#B2816B'))+labs(x='Adjusted RR (95% CI)',y=NULL,color=NULL,title='A childhood reporting gradient extends into adulthood')
savep(p,'04_child_phenotype_adult_RR',11,4)
a<-read.csv(file.path(out,'common_age_absolute_risks.csv'));z<-a[a$measure%in%c('female_risk','male_risk'),];z$cohort<-factor(z$cohort,levels=c('NCDS','BCS70','MCS'),labels=c('NCDS\n1958 birth cohort','BCS70\n1970 birth cohort','MCS\n2000-2002 birth cohort'));z$sex<-factor(z$measure,levels=c('female_risk','male_risk'),labels=c('Female','Male'));pd<-position_dodge(width=.35)
p<-ggplot(z,aes(cohort,estimate,color=sex))+geom_errorbar(aes(ymin=lower,ymax=upper),width=.1,position=pd)+geom_point(size=3,position=pd)+scale_y_continuous(labels=scales::label_percent(),limits=c(0,.17))+scale_color_manual(values=c('#B2816B','#557D9E'))+labs(x=NULL,y='Standardized recent-symptom risk (95% CI)',color=NULL,title='Relative male susceptibility coexists with different absolute burden')
savep(p,'05_common_age_absolute_risks',9,4.5)
if(file.exists(file.path(out,'MI_IPCW_core_results.csv'))){mi<-read.csv(file.path(out,'MI_IPCW_core_results.csv'));v2<-read.csv(file.path(old,'model_RR_results.csv'));v2<-v2[v2$method%in%c('IPCW','monotone_unweighted')&v2$endpoint%in%c('transition_0_to_1','transition_1_to_1','adult_repeated_burden')&v2$term%in%names(labs),];v2$RR<-v2$estimate;z<-rbind(mi[c('cohort','endpoint','method','term','RR','lower','upper')],v2[c('cohort','endpoint','method','term','RR','lower','upper')]);z$panel<-paste(z$cohort,ifelse(z$endpoint=='transition_0_to_1','Symptom emergence',ifelse(z$endpoint=='transition_1_to_1','Symptom persistence','Adult respiratory burden')),sep=': ');z$factor<-factor(labs[z$term],levels=rev(labs));z$method<-factor(z$method,levels=c('monotone_unweighted','IPCW','MI_IPCW'),labels=c('Complete predictors','Complete predictors + IPCW','MI + IPCW'));pd<-position_dodge(width=.65)
 p<-ggplot(z,aes(RR,factor,color=method))+geom_vline(xintercept=1,lty=2,color='grey70')+geom_errorbar(aes(xmin=lower,xmax=upper),orientation='y',width=.12,position=pd,linewidth=.45)+geom_point(size=1.8,position=pd)+facet_wrap(~panel,scales='free_y',ncol=2)+scale_x_log10()+scale_color_manual(values=c('#9DA8B0','#B2816B','#557D9E'))+labs(x='Adjusted RR (95% CI)',y=NULL,color=NULL,title='Core association estimates after multiple imputation and dropout weighting')
 savep(p,'06_MI_IPCW_stability',12,8)
 traces<-read.csv(file.path(out,'MI_chain_traces.csv'));traces<-traces[is.finite(traces$chain_mean),];traces$chain_mean[traces$term!='bmi3_z']<-traces$chain_mean[traces$term!='bmi3_z']-1;traces$panel<-paste(traces$cohort,labs[traces$term],sep=': ')
 p<-ggplot(traces,aes(iteration,chain_mean,group=interaction(cohort,term,imputation)))+geom_line(color='#557D9E',alpha=.23,linewidth=.35)+facet_wrap(~panel,scales='free_y',ncol=4)+labs(x='Iteration',y='Mean of imputed values within chain',title='Imputation trace diagnostics (20 chains per factor)')
 savep(p,'07_MI_chain_traces',14,10)
}
writeLines(c('R quantitative-grid figure contract: 90% CI for equivalence; 95% CI for stage/association and absolute-risk estimates.', 'Hero figure: observed weighted adult category proportions among six-wave participants; labels give unweighted group sizes.', 'Figures do not establish causality or uninterrupted clinical persistence; MI trace plots use 20 chains.', 'PNG 320dpi, PDF, editable SVG; white backgrounds; Arial; restrained palette.'),file.path(out,'figure_contract.txt'))
cat('V3 figures completed\n')
